import { test, expect } from '@playwright/test';

test.describe('Notification Filtering by Type', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should filter notifications by type (info, warning, error)', async ({ page }) => {
    // Verify notifications container is visible
    const notificationsContainer = page.getByRole('region', { name: /notifications/i });
    await expect(notificationsContainer).toBeVisible();

    // Verify filter buttons are visible
    const filterButtons = page.getByRole('button', { name: /filter by type/i });
    await expect(filterButtons).toBeVisible();

    // Click on 'info' filter button
    const infoFilterButton = page.getByRole('button', { name: /info/i });
    await infoFilterButton.click();

    // Verify 'info' filter is active
    await expect(infoFilterButton).toHaveClass(/active/);

    // Verify only info notifications are displayed
    const infoNotifications = page.getByRole('alert', { name: /info/i });
    const errorNotifications = page.getByRole('alert', { name: /error/i });
    const warningNotifications = page.getByRole('alert', { name: /warning/i });

    await expect(infoNotifications).toBeVisible();
    await expect(errorNotifications).not.toBeVisible();
    await expect(warningNotifications).not.toBeVisible();

    // Click on 'warning' filter button
    const warningFilterButton = page.getByRole('button', { name: /warning/i });
    await warningFilterButton.click();

    // Verify 'warning' filter is active
    await expect(warningFilterButton).toHaveClass(/active/);

    // Verify only warning notifications are displayed
    await expect(infoNotifications).not.toBeVisible();
    await expect(warningNotifications).toBeVisible();
    await expect(errorNotifications).not.toBeVisible();

    // Click on 'error' filter button
    const errorFilterButton = page.getByRole('button', { name: /error/i });
    await errorFilterButton.click();

    // Verify 'error' filter is active
    await expect(errorFilterButton).toHaveClass(/active/);

    // Verify only error notifications are displayed
    await expect(infoNotifications).not.toBeVisible();
    await expect(warningNotifications).not.toBeVisible();
    await expect(errorNotifications).toBeVisible();
  });

  test('should handle filter button clicks when no notifications exist', async ({ page }) => {
    // Navigate to notifications page
    await page.goto('/notifications');

    // Clear existing notifications
    const clearButton = page.getByRole('button', { name: /clear all/i });
    await clearButton.click();

    // Verify notifications container is empty
    const notificationsContainer = page.getByRole('region', { name: /notifications/i });
    await expect(notificationsContainer).toBeVisible();

    const noNotificationsMessage = page.getByText(/no notifications found/i);
    await expect(noNotificationsMessage).toBeVisible();

    // Click on 'info' filter button
    const infoFilterButton = page.getByRole('button', { name: /info/i });
    await infoFilterButton.click();

    // Verify 'info' filter is active
    await expect(infoFilterButton).toHaveClass(/active/);

    // Verify no notifications are displayed
    await expect(noNotificationsMessage).toBeVisible();

    // Click on 'warning' filter button
    const warningFilterButton = page.getByRole('button', { name: /warning/i });
    await warningFilterButton.click();

    // Verify 'warning' filter is active
    await expect(warningFilterButton).toHaveClass(/active/);

    // Verify no notifications are displayed
    await expect(noNotificationsMessage).toBeVisible();

    // Click on 'error' filter button
    const errorFilterButton = page.getByRole('button', { name: /error/i });
    await errorFilterButton.click();

    // Verify 'error' filter is active
    await expect(errorFilterButton).toHaveClass(/active/);

    // Verify no notifications are displayed
    await expect(noNotificationsMessage).toBeVisible();
  });
});
